const leads = $input.all().map(item => item.json);

const totalLeads = leads.length;

const newLeads = leads.filter(
  lead => String(lead.status || '').toLowerCase() === 'new'
    || String(lead.status || '').toLowerCase() === 'new lead'
).length;

const qualifiedLeads = leads.filter(
  lead => String(lead.status || '').toLowerCase() === 'qualified'
).length;

const convertedLeads = leads.filter(
  lead => String(lead.status || '').toLowerCase() === 'converted'
).length;

const scores = leads
  .map(lead => Number(lead.lead_score))
  .filter(score => !isNaN(score));

const averageLeadScore = scores.length
  ? scores.reduce((sum, score) => sum + score, 0) / scores.length
  : 0;

// Find top lead source
const sourceCounts = {};

leads.forEach(lead => {
  const source = lead.source || 'Unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + 1;
});

const topLeadSource = Object.entries(sourceCounts)
  .sort((a, b) => b[1] - a[1])[0] || ['Unknown', 0];

// Top 5 leads
const top5Leads = [...leads]
  .sort((a, b) => Number(b.lead_score || 0) - Number(a.lead_score || 0))
  .slice(0, 5)
  .map(lead => ({
    name: lead.name,
    company: lead.company,
    lead_score: Number(lead.lead_score || 0),
    status: lead.status,
    source: lead.source
  }));

// Conversion rate
const conversionRate = totalLeads
  ? (convertedLeads / totalLeads) * 100
  : 0;

return [
  {
    json: {
      totalLeads,
      newLeads,
      qualifiedLeads,
      convertedLeads,
      averageLeadScore: Number(averageLeadScore.toFixed(2)),
      topLeadSource: topLeadSource[0],
      topLeadSourceCount: topLeadSource[1],
      top5Leads,
      conversionRate: Number(conversionRate.toFixed(2))
    }
  }
];
